const fs = require('fs');
const path = require('path');

// Create temp directory
const tempDir = "C:\\Users\\itama\\Dropbox\\Docs Itamar\\Scripts\\Claude-code\\temp";
if (!fs.existsSync(tempDir)) {
  fs.mkdirSync(tempDir, { recursive: true });
}

// Write raw data to file - NO PARSING AT ALL
const timestamp = Date.now();
const dataFile = path.join(tempDir, `invoice-data-${timestamp}.json`);

// Save everything exactly as received
const rawData = {
  vendor: $json.vendor,
  text: $json.text,
  emailId: $json.emailId,
  threadId: $json.threadId
};

fs.writeFileSync(dataFile, JSON.stringify(rawData, null, 2), 'utf8');

return {
  json: {
    dataFile: dataFile
  }
};

const fs = require('fs');

// Get command output
const stdout = $input.first().json.stdout || "";
const stderr = $input.first().json.stderr || "";
const code = $input.first().json.code || 0;

// Clean up temp file if it still exists
const dataFile = $('Write Raw Data to File').item.json.dataFile;
if (dataFile && fs.existsSync(dataFile)) {
  try {
    fs.unlinkSync(dataFile);
  } catch (e) {
    // Ignore cleanup errors
  }
}

// Check for errors
if (code !== 0) {
  return {
    json: {
      error: "Command failed",
      stderr: stderr,
      stdout: stdout,
      exitCode: code
    }
  };
}

// Parse JSON from stdout
let invoiceData;
try {
  // Try direct JSON parse
  invoiceData = JSON.parse(stdout);
} catch (error) {
  // Try to extract from markdown code block
  const jsonMatch = stdout.match(/```json\n([\s\S]*?)\n```/);
  if (jsonMatch) {
    try {
      invoiceData = JSON.parse(jsonMatch[1]);
    } catch (e) {
      return {
        json: {
          error: "Could not parse JSON from code block",
          rawOutput: stdout,
          stderr: stderr
        }
      };
    }
  } else {
    // Try to find any JSON object in output
    const objMatch = stdout.match(/\{[\s\S]*\}/);
    if (objMatch) {
      try {
        invoiceData = JSON.parse(objMatch[0]);
      } catch (e) {
        return {
          json: {
            error: "Could not parse JSON object",
            rawOutput: stdout,
            stderr: stderr
          }
        };
      }
    } else {
      return {
        json: {
          error: "No JSON found in output",
          rawOutput: stdout,
          stderr: stderr
        }
      };
    }
  }
}

return {
  json: invoiceData
};
